typedef float time_value_t;

enum game_mode_t
{
    GAME_MODE_CAREER,
    GAME_MODE_FREESURF_INFINITE,
    GAME_MODE_FREESURF_HIGHSCORE,
    GAME_MODE_FREESURF_ICON,
    GAME_MODE_PRACTICE,
    GAME_MODE_TIME_ATTACK,
    GAME_MODE_METER_ATTACK,
    GAME_MODE_SEA_HORSE,
    GAME_MODE_HEAD_TO_HEAD,
    GAME_MODE_PUSH
};

class game
{
public:
    bool is_competition_level(void);
    game_mode_t get_game_mode(void);
};

class JudgingSystem
{
public:
    bool IsCompetitionOver(void) const;
};

class beach
{
public:
    JudgingSystem judges;
};

class IGOPrintQueue
{
public:
    void clear();
};

class BoxText
{
public:
    float time;
};

class PauseMenuSystem
{
public:
    enum
    {
        PauseMenu,
        TimeAttackPauseMenu,
        TutorialPauseMenu,
        EndRunMenu,
        HeatMidMenu,
        HeatEndMenu,
        CompEndMenu
    };

    virtual void UpdateButtonDown();
    virtual void startDraw(int menu_num = -1, const bool pauseGame = true);
};

class FEManager
{
public:
    void *IGO;
    PauseMenuSystem *pms;
};

extern game *g_game_ptr;
extern beach *g_beach_ptr;

class IGOFrontEnd
{
public:
    enum RUNSTATE
    {
        RUNSTATE_NORMAL,
        RUNSTATE_GOALS,
        RUNSTATE_REWARDS,
        RUNSTATE_STATS,
        RUNSTATE_HIGHSCORE,
        RUNSTATE_PHOTOS,
        RUNSTATE_SAVE,
        RUNSTATE_JUDGE,
        RUNSTATE_RANK,
        RUNSTATE_MEDAL,
        RUNSTATE_PUSH,
        RUNSTATE_TIME_ATTACK,
        RUNSTATE_METER_ATTACK,
        RUNSTATE_HEAD_TO_HEAD,
        RUNSTATE_LAST
    };

    FEManager *manager;
    RUNSTATE runState;
    IGOPrintQueue printQueue;
    BoxText *otherText;

    void ShowAccompBackground(const bool bgOn, const int hLineFlags = 0, const int vLineFlags = 0);
    void UpdateStateLast(time_value_t time_inc);
};

void IGOFrontEnd::UpdateStateLast(time_value_t time_inc)
{
    ShowAccompBackground(false);
    runState = RUNSTATE_NORMAL;

    // clear the print queue so no remaining messages will be shown on the next run
    printQueue.clear(); 
    if (otherText) otherText->time = 0.0f;

    // clear the print queue so no remaining messages will be shown on the next run
    printQueue.clear(); 
    if (otherText) otherText->time = 0.0f;

    if (g_game_ptr->is_competition_level() && g_game_ptr->get_game_mode() == GAME_MODE_CAREER)
    {
        if (!g_beach_ptr->judges.IsCompetitionOver())
        {
            manager->pms->startDraw(PauseMenuSystem::HeatEndMenu);
            manager->pms->UpdateButtonDown();
        }
        else
        {
            manager->pms->startDraw(PauseMenuSystem::CompEndMenu);
            manager->pms->UpdateButtonDown();
        }
    }
    else
    {
        manager->pms->startDraw(PauseMenuSystem::EndRunMenu);
        manager->pms->UpdateButtonDown();
    }
}
